 rtwb14_phy_board board{};assert(rtwb14_phy_board_validate(nullptr)==EINVAL);assert(rtwb14_phy_board_validate(&board)==ENODATA);assert(rtwb14_phy_size()<=RTWB14_PHY_SCRATCH_BYTES);
