 {B14PHYFixture f(6,RTWB14_BOARD_EXT_PA);assert(!rtwb14_phy_load(f.phy)&&!rtwb14_phy_tune(f.phy,6,&f.power)&&!rtwb14_phy_calibrate(f.phy));f.bus.timeout=true;f.bus.put(0x2d9c,0,1);assert(rtwb14_phy_calibrate(f.phy)&&!rtwb14_phy_get_status(f.phy).calibrated&&rtwb14_phy_get_status(f.phy).iqk_paths==0);}
 {B14PHYFixture f;assert(!rtwb14_phy_load(f.phy)&&!rtwb14_phy_tune(f.phy,36,&f.power));f.bus.inject_thermal=true;f.bus.thermal={20,40,50,60};assert(!rtwb14_phy_calibrate(f.phy));f.bus.thermal={30,30,60,50};f.bus.writes.clear();assert(!rtwb14_phy_track(f.phy));std::array<unsigned,4>comp{};unsigned path=0;for(auto w:f.bus.writes){if(w.address==0x1b00)path=(w.value>>1)&3;if(w.address==0x1b58)comp[path]=w.value&63;}printf("thermal compensation %u %u %u %u\n",comp[0],comp[1],comp[2],comp[3]);fflush(stdout);assert((comp==std::array<unsigned,4>{2,63,2,63}));}
