 for(unsigned ch:{6U,36U,165U}){B14PHYFixture f;assert(!rtwb14_phy_load(f.phy));assert(!rtwb14_phy_tune(f.phy,(uint8_t)ch,&f.power));auto s=rtwb14_phy_get_status(f.phy);assert(s.tables&&s.channel==ch&&!s.calibrated&&!s.tx_enabled&&f.bus.reg[0x522]==255);int e=rtwb14_phy_calibrate(f.phy);s=rtwb14_phy_get_status(f.phy);printf("B14 channel%u cal%d iqk%x dpk%x lck%x gap%x ops%u\n",ch,e,s.iqk_paths,s.dpk_paths,s.lck_synths,s.txgapk_paths,f.bus.operations);fflush(stdout);assert(!e&&s.calibrated);}
